  /** UNVERIFIED (TC_GUIDE_003 — network-payload pricing-absence check). */
  async captureNetworkResponsesDuringNavigation(urlPattern: RegExp, action: () => Promise<void>): Promise<string[]> {
    const bodies: string[] = [];
    const handler = async (response: import('@playwright/test').Response) => {
      if (urlPattern.test(response.url())) {
        try {
          bodies.push(await response.text());
        } catch {
          /* non-text response body, ignore */
        }
      }
    };
    this.page.on('response', handler);
    await action();
    this.page.off('response', handler);
    return bodies;
  }

  assertNoPricingKeywordInPayloads(bodies: string[]): void {
    const pricingPattern = /"(price|amount|total|charge)"\s*:/i;
    for (const body of bodies) {
      if (pricingPattern.test(body)) {
        throw new Error('Pricing-related field found in a network response payload during Guide session navigation.');
      }
    }
  }

